# HR Tool Attendance - self-contained extension installer (Windows).
# Generated by scripts/build-installers.py - do not edit by hand.
# Run:  powershell -ExecutionPolicy Bypass -File install-hr-attendance.ps1
$ErrorActionPreference = 'Stop'

$Dest = Join-Path $env:LOCALAPPDATA 'HRToolAttendance'

Write-Host 'HR Tool Attendance - installer' -ForegroundColor Cyan
Write-Host ''
if (Test-Path $Dest) { Remove-Item -Recurse -Force $Dest }

function Write-Ext($rel, $b64) {
  $p = Join-Path $Dest $rel
  $dir = Split-Path $p -Parent
  New-Item -ItemType Directory -Force -Path $dir | Out-Null
  [IO.File]::WriteAllBytes($p, [Convert]::FromBase64String($b64))
}

Write-Ext 'README.md' ''
Write-Ext 'background.js' ''
Write-Ext 'icons/icon128.png' ''
Write-Ext 'icons/icon16.png' 'iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAYAAAAf8/9hAAAAVElEQVR42mNgQAP+bk//48MMuAAhjXgNIlUzhiHoErgAVgNwaSZWnIGQImQ+NnkGXIpxiQ2MAfgCk6ABhFzEQExIEx2IZEUjxQmJKkmZ4sxESXYGADAXawAl9JwwAAAAAElFTkSuQmCC'
Write-Ext 'icons/icon48.png' ''
Write-Ext 'manifest.json' ''
Write-Ext 'popup.html' ''
Write-Ext 'popup.js' ''

Write-Host 'Extension installed at:'
Write-Host "  $Dest" -ForegroundColor Green
Set-Clipboard -Value $Dest
Write-Host '  (path copied to your clipboard)'
Write-Host ''
Write-Host 'Next, in your browser (works the same in all of these):'
Write-Host '  1. Open your browsers extensions page:'
Write-Host '       Chrome   ->  chrome://extensions'
Write-Host '       Edge     ->  edge://extensions'
Write-Host '       Brave    ->  brave://extensions'
Write-Host '       Opera    ->  opera://extensions'
Write-Host '       Vivaldi  ->  vivaldi://extensions'
Write-Host "  2. Turn ON 'Developer mode' (top-right toggle; Edge: bottom-left)"
Write-Host "  3. Click 'Load unpacked'"
Write-Host '  4. Paste the path above into the folder box and choose it'
Write-Host "  5. Pin 'HR Tool Attendance', click it, sign in with your work email"
Write-Host '     + the 6-digit code we email you'
Write-Host ''
Write-Host 'Shortcuts once connected:'
Write-Host '  Alt+Shift+I  = clock in'
Write-Host '  Alt+Shift+O  = clock out'

